SELECT match, COUNT(*) n FROM offers WHERE created_at >= '2026-10-30' GROUP BY match ORDER BY n DESC;
WITH r AS (SELECT json_extract(j.value,'$.verdict') v FROM offers o, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= '2026-10-30' AND o.match_checks_json IS NOT NULL) SELECT v, COUNT(*) n FROM r GROUP BY v ORDER BY n DESC;
WITH r AS (SELECT lower(substr(json_extract(j.value,'$.name'),1,45)) req, json_extract(j.value,'$.verdict') v FROM offers o, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= '2026-10-30' AND o.match_checks_json IS NOT NULL) SELECT req, SUM(v='no') no_, SUM(v='unknown') unk, SUM(v='yes') yes_ FROM r GROUP BY req HAVING no_+unk >= 15 ORDER BY no_+unk DESC LIMIT 30;
WITH r AS (SELECT lower(substr(json_extract(j.value,'$.name'),1,45)) req, json_extract(j.value,'$.verdict') v, json_extract(j.value,'$.found') f FROM offers o JOIN tender_items i ON i.id = o.item_id, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= '2026-10-30' AND o.match_checks_json IS NOT NULL AND (lower(i.name) LIKE '%аккумулятор%' OR lower(i.name) LIKE '%батар%' OR lower(i.name) LIKE '%элемент питания%')) SELECT req, SUM(v='no') no_, SUM(v='unknown') unk, SUM(v='yes') yes_, substr(MAX(CASE WHEN v='no' THEN f END),1,40) found_no FROM r GROUP BY req ORDER BY no_+unk DESC LIMIT 20;
WITH r AS (SELECT lower(substr(json_extract(j.value,'$.name'),1,45)) req, json_extract(j.value,'$.verdict') v FROM offers o JOIN tender_items i ON i.id = o.item_id, json_each(o.match_checks_json,'$.rows') j WHERE o.created_at >= '2026-10-30' AND o.match_checks_json IS NOT NULL AND (lower(i.name) LIKE '%бахил%' OR lower(i.name) LIKE '%перчат%' OR lower(i.name) LIKE '%шприц%' OR lower(i.name) LIKE '%маск%')) SELECT req, SUM(v='no') no_, SUM(v='unknown') unk, SUM(v='yes') yes_ FROM r GROUP BY req ORDER BY no_+unk DESC LIMIT 15;
WITH h AS (SELECT substr(url, instr(url,'://')+3) u, match_checks_json c FROM offers WHERE created_at >= '2026-10-30' AND match_checks_json IS NOT NULL AND url LIKE 'http%'), r AS (SELECT substr(u,1,instr(u||'/','/')-1) host, json_extract(j.value,'$.verdict') v FROM h, json_each(h.c,'$.rows') j) SELECT host, COUNT(*) req_total, SUM(v='unknown') unk, ROUND(100.0*SUM(v='unknown')/COUNT(*)) unk_pct, SUM(v='yes') yes_ FROM r GROUP BY host HAVING req_total >= 40 ORDER BY unk DESC LIMIT 20
